// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IRouter} from "./interfaces/IRouter.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {ERC2771ContextUpgradeable} from "@openzeppelin/contracts-upgradeable/metatx/ERC2771ContextUpgradeable.sol";
import {ContextUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ContextUpgradeable.sol";

/// @notice Interface for MUSDSavingsRate vault
interface IMUSDSavingsRate {
    /// @notice Receives MUSD protocol yield and distributes it to sMUSD holders
    /// @param amount The amount of MUSD yield to distribute
    function receiveProtocolYield(uint256 amount) external;
}

/// @title Yield Converter
/// @notice Converts protocol yield from BTC and whitelisted ERC20 tokens to MUSD via Router swaps,
///         then distributes MUSD through the MUSDSavingsRate vault.
contract YieldConverter is
    Initializable,
    OwnableUpgradeable,
    ERC2771ContextUpgradeable
{
    using SafeERC20 for IERC20;

    /// @dev We need to store the forwarder address because ERC2771ContextUpgradeable
    ///      doesn't expose it publicly
    /// @custom:oz-upgrades-unsafe-allow state-variable-immutable
    address public immutable forwarder;

    /// @notice The MUSD token contract address
    IERC20 public musdToken;
    /// @notice The BTC token contract address
    IERC20 public btcToken;
    /// @notice The router contract
    IRouter public router;
    /// @notice The MUSD Savings Rate vault contract
    IMUSDSavingsRate public musdSavingsRate;
    /// @notice Maximum slippage tolerance in basis points (e.g., 200 = 2%)
    uint256 public maxSlippageBps;
    /// @notice Mapping of whitelisted tokens that can be swapped to MUSD
    mapping(address => bool) public whitelistedTokens;

    event MaxSlippageBpsUpdated(uint256 oldSlippage, uint256 newSlippage);
    event RouterUpdated(address indexed oldRouter, address indexed newRouter);
    event TokenWhitelistUpdated(address indexed token, bool whitelisted);
    event YieldConverted(
        address indexed sender,
        address indexed token,
        uint256 tokenAmount,
        uint256 musdAmount
    );
    event YieldDistributed(uint256 musdAmount);
    event Initialized(
        address btcToken,
        address musdToken,
        address router,
        address musdSavingsRate
    );

    error ZeroAddress();
    error ZeroAmount();
    error SlippageTooHigh();
    error InsufficientBalance();
    error PoolDoesNotExist();
    error TokenNotWhitelisted();

    /// @notice Constructor to set the trusted forwarder for ERC2771.
    /// @param _forwarder The address of the trusted forwarder
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(address _forwarder) ERC2771ContextUpgradeable(_forwarder) {
        if (_forwarder == address(0)) revert ZeroAddress();
        forwarder = _forwarder; // immutable so can set in constructor
        _disableInitializers();
    }

    /// @notice Initializes the YieldConverter contract.
    /// @param _btcToken The address of the BTC token contract
    /// @param _musdToken The address of the MUSD token contract
    /// @param _router The address of the router contract
    /// @param _musdSavingsRate The address of the MUSD Savings Rate vault contract
    function initialize(
        address _btcToken,
        address _musdToken,
        address _router,
        address _musdSavingsRate
    ) external initializer {
        if (_btcToken == address(0)) revert ZeroAddress();
        if (_musdToken == address(0)) revert ZeroAddress();
        if (_router == address(0)) revert ZeroAddress();
        if (_musdSavingsRate == address(0)) revert ZeroAddress();

        __Ownable_init();

        btcToken = IERC20(_btcToken);
        musdToken = IERC20(_musdToken);
        router = IRouter(_router);
        musdSavingsRate = IMUSDSavingsRate(_musdSavingsRate);

        maxSlippageBps = 200; // Default 2% slippage tolerance

        emit Initialized(_btcToken, _musdToken, _router, _musdSavingsRate);
    }

    /// @notice Receives BTC yield, converts it to MUSD which is then transferred
    ///         to the MUSDSavingsRate vault to be distributed among sMUSD holders.
    /// @dev Anyone can call this function. Converts amount of BTC balance
    ///      to MUSD using the BTC/MUSD pool, then distributes the MUSD as yield.
    /// @dev BTC is transferred to this contract natively, so we don't need to
    ///      transfer it from the sender.
    /// @param amount The amount of BTC yield to convert and distribute
    function receiveProtocolYieldInBTC(uint256 amount) external {
        if (amount == 0) revert ZeroAmount();
        if (btcToken.balanceOf(address(this)) < amount)
            revert InsufficientBalance();

        // Convert BTC to MUSD using Tigris BTC/MUSD pool
        uint256 musdFromBtc = _swapToMUSD(address(btcToken), amount, false);

        // Use forceApprove to handle non-standard ERC20 tokens safely
        musdToken.forceApprove(address(musdSavingsRate), musdFromBtc);
        musdSavingsRate.receiveProtocolYield(musdFromBtc);

        emit YieldDistributed(musdFromBtc);
    }

    /// @notice Receives whitelisted ERC20 token yield, converts it to MUSD, and distributes it.
    /// @dev Anyone can call this function. Converts amount of whitelisted token balance
    ///      to MUSD using the token/MUSD pool (if exists), then distributes the MUSD as yield.
    /// @dev The token must be whitelisted and have a valid pool with MUSD.
    /// @param _token The address of the whitelisted token to convert
    /// @param _amount The amount of tokens to convert and distribute
    function receiveProtocolYieldInERC20(
        address _token,
        uint256 _amount
    ) external {
        if (_amount == 0) revert ZeroAmount();
        if (!whitelistedTokens[_token]) revert TokenNotWhitelisted();

        IERC20 token = IERC20(_token);
        if (token.balanceOf(address(this)) < _amount)
            revert InsufficientBalance();

        // Convert token to MUSD using Router (try both volatile and stable pools)
        uint256 musdFromToken = _swapToMUSD(_token, _amount, true);

        // Use forceApprove to handle non-standard ERC20 tokens safely
        musdToken.forceApprove(address(musdSavingsRate), musdFromToken);
        musdSavingsRate.receiveProtocolYield(musdFromToken);

        emit YieldDistributed(musdFromToken);
    }

    /// @notice Updates the maximum slippage tolerance for BTC to MUSD swaps.
    /// @dev Can only be called by the contract owner. Cannot exceed 100% (10000 bps).
    /// @param _maxSlippageBps New maximum slippage in basis points (e.g., 100 = 1%)
    function setMaxSlippageBps(uint256 _maxSlippageBps) external onlyOwner {
        if (_maxSlippageBps > 10000) revert SlippageTooHigh();
        uint256 oldSlippage = maxSlippageBps;
        maxSlippageBps = _maxSlippageBps;
        emit MaxSlippageBpsUpdated(oldSlippage, _maxSlippageBps);
    }

    /// @notice Updates the router address.
    /// @dev Can only be called by the contract owner.
    /// @param _router The new router address
    function setRouter(address _router) external onlyOwner {
        if (_router == address(0)) revert ZeroAddress();
        address oldRouter = address(router);
        router = IRouter(_router);
        emit RouterUpdated(oldRouter, _router);
    }

    /// @notice Updates the whitelist status of a token.
    /// @dev Can only be called by the contract owner.
    /// @param _token The token address to update
    /// @param _whitelisted Whether the token should be whitelisted
    function setTokenWhitelist(
        address _token,
        bool _whitelisted
    ) external onlyOwner {
        if (_token == address(0)) revert ZeroAddress();
        whitelistedTokens[_token] = _whitelisted;
        emit TokenWhitelistUpdated(_token, _whitelisted);
    }

    /// @notice Receives native BTC sent to this contract
    /// @dev Anyone can send native BTC to this contract via a direct transfer.
    ///      The contract uses ERC20-wrapped BTC (btcToken) for swaps, and then
    ///      processes it via receiveProtocolYieldInBTC().
    receive() external payable {
        if (msg.value == 0) revert ZeroAmount();
    }

    /// @dev Swap any ERC20 token to MUSD using the Router.
    /// @param _token The address of the token to swap
    /// @param _amount The amount of tokens to swap
    /// @param _tryStablePool Whether to try stable pool as fallback if volatile pool doesn't exist
    /// @return musdReceived The amount of MUSD received from the swap
    function _swapToMUSD(
        address _token,
        uint256 _amount,
        bool _tryStablePool
    ) internal returns (uint256 musdReceived) {
        // Create route for token -> MUSD swap (volatile pool)
        IRouter.Route[] memory routes = new IRouter.Route[](1);
        routes[0] = IRouter.Route({
            from: _token,
            to: address(musdToken),
            stable: false,
            factory: router.defaultFactory()
        });

        // Get the expected output amount
        uint256[] memory expectedAmounts = router.getAmountsOut(
            _amount,
            routes
        );
        uint256 expectedMusd = expectedAmounts[expectedAmounts.length - 1];

        // If volatile pool doesn't exist or has no liquidity, try stable pool
        if (expectedMusd == 0 && _tryStablePool) {
            routes[0].stable = true;
            expectedAmounts = router.getAmountsOut(_amount, routes);
            expectedMusd = expectedAmounts[expectedAmounts.length - 1];
        }

        // If no pool exists, revert
        if (expectedMusd == 0) revert PoolDoesNotExist();

        // Calculate minimum acceptable output with slippage tolerance
        uint256 minMusdOut = (expectedMusd * (10000 - maxSlippageBps)) / 10000;

        // Approve router to spend tokens
        IERC20(_token).forceApprove(address(router), _amount);

        // Perform the swap using Router
        uint256[] memory amounts = router.swapExactTokensForTokens(
            _amount,
            minMusdOut,
            routes,
            address(this),
            block.timestamp
        );

        musdReceived = amounts[amounts.length - 1];

        // Emit yield converted event
        emit YieldConverted(_msgSender(), _token, _amount, musdReceived);

        return musdReceived;
    }

    /// @dev Override _msgSender to support ERC2771 meta-transactions.
    ///      Needed given OwnableUpgradeable inherits from ContextUpgradeable
    ///      which defines _msgSender().
    function _msgSender()
        internal
        view
        override(ContextUpgradeable, ERC2771ContextUpgradeable)
        returns (address sender)
    {
        return ERC2771ContextUpgradeable._msgSender();
    }

    /// @dev Override _msgData to support ERC2771 meta-transactions.
    ///      Needed given ERC20Upgradeable inherits from ContextUpgradeable
    ///      which defines _msgData().
    function _msgData()
        internal
        view
        override(ContextUpgradeable, ERC2771ContextUpgradeable)
        returns (bytes calldata)
    {
        return ERC2771ContextUpgradeable._msgData();
    }

    /// @dev Override _contextSuffixLength to support ERC2771 meta-transactions.
    ///      Needed given ERC20Upgradeable inherits from ContextUpgradeable
    ///      which defines _contextSuffixLength().
    function _contextSuffixLength()
        internal
        view
        override(ContextUpgradeable, ERC2771ContextUpgradeable)
        returns (uint256)
    {
        return ERC2771ContextUpgradeable._contextSuffixLength();
    }
}

